-- Coldburrow Xenobreeder (creature 36884): the Superior Skeech-pen beast in Coldburrow Cavern that drops Xenobreeder's Head (item 6954), the item that starts Off with Her Head! (quest 3783).
-- The world database had no spawn of it (build_spawns only places quest givers and objectives; it is neither), so the quest could never start.
-- Positions: the three quest/marker locations inside its pin cluster (WorldLocation2 40187, 9049, 47901), which carry the cavern floor height. Drops: archived Jabbithole page, 44 items over 1977 kills.
-- Generated by hand from wildstar-archive data on 2026-11-02. Entity ids 1300001+, loot group 4000001+.
DELETE FROM `entity_loot` WHERE `lootGroupId` >= 4000000 AND `lootGroupId` < 4100000;
DELETE FROM `loot_item` WHERE `id` >= 4000000 AND `id` < 4100000;
DELETE FROM `loot_group` WHERE `id` >= 4000000 AND `id` < 4100000 AND `parentId` IS NOT NULL;
DELETE FROM `loot_group` WHERE `id` >= 4000000 AND `id` < 4100000;
DELETE FROM `entity_stats` WHERE `Id` BETWEEN 1300001 AND 1300099;
DELETE FROM `entity` WHERE `Id` BETWEEN 1300001 AND 1300099;

